"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_NUMERIC = r"(?:0|[1-9][0-9]*)"
_IDENTIFIER = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    r"^"
    + _NUMERIC
    + r"\."
    + _NUMERIC
    + r"\."
    + _NUMERIC
    + r"(?:-(?P<prerelease>"
    + _IDENTIFIER
    + r"(?:\."
    + _IDENTIFIER
    + r")*))?"
    + r"(?:\+(?P<build>"
    + _IDENTIFIER
    + r"(?:\."
    + _IDENTIFIER
    + r")*))?"
    + r"$"
)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


@dataclass(frozen=True)
class _Comparator:
    operator: str
    version: Version


def _invalid_version(text: str) -> ValueError:
    return ValueError(f"invalid semantic version: {text!r}")


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid semantic version: {text!r}")

    match = _VERSION_RE.match(text)
    if match is None:
        raise _invalid_version(text)

    prerelease_text = match.group("prerelease")
    build_text = match.group("build")
    prerelease = tuple(prerelease_text.split(".")) if prerelease_text else ()
    build = tuple(build_text.split(".")) if build_text else ()

    for identifier in prerelease:
        if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
            raise _invalid_version(text)

    major, minor, patch = text.split("-", 1)[0].split("+", 1)[0].split(".")
    return Version(int(major), int(minor), int(patch), prerelease, build)


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def _compare_versions(a: Version, b: Version) -> int:
    for left, right in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        if left != right:
            return -1 if left < right else 1

    return _compare_prerelease(a.prerelease, b.prerelease)


def _compare_prerelease(a: tuple[str, ...], b: tuple[str, ...]) -> int:
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for left, right in zip(a, b):
        left_numeric = left.isdigit()
        right_numeric = right.isdigit()

        if left_numeric and right_numeric:
            left_value = int(left)
            right_value = int(right)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        elif left != right:
            return -1 if left < right else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_versions(_as_version(a), _as_version(b))


def _parse_comparator(token: str) -> _Comparator:
    for operator in (">=", "<=", "^", "~", ">", "<", "="):
        if token.startswith(operator):
            version_text = token[len(operator) :]
            break
    else:
        operator = "="
        version_text = token

    if not version_text:
        raise ValueError(f"invalid comparator: {token!r}")
    return _Comparator(operator, parse(version_text))


def _parse_range(range_: str) -> list[list[_Comparator]]:
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    sets: list[list[_Comparator]] = []
    for part in range_.split("||"):
        part = part.strip()
        if not part:
            raise ValueError(f"invalid range: {range_!r}")
        tokens = part.split()
        if not tokens:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append([_parse_comparator(token) for token in tokens])
    return sets


def _caret_upper(version: Version) -> Version:
    if version.major > 0:
        return Version(version.major + 1, 0, 0)
    if version.minor > 0:
        return Version(0, version.minor + 1, 0)
    return Version(0, 0, version.patch + 1)


def _tilde_upper(version: Version) -> Version:
    return Version(version.major, version.minor + 1, 0)


def _comparator_holds(version: Version, comparator: _Comparator) -> bool:
    bound = comparator.version
    operator = comparator.operator
    comparison = _compare_versions(version, bound)

    if operator == "=":
        return comparison == 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0
    if operator == "^":
        return comparison >= 0 and _compare_versions(version, _caret_upper(bound)) < 0
    if operator == "~":
        return comparison >= 0 and _compare_versions(version, _tilde_upper(bound)) < 0

    raise ValueError(f"invalid comparator operator: {operator!r}")


def _satisfies_set(version: Version, comparators: list[_Comparator]) -> bool:
    if version.prerelease:
        same_patch = any(
            comparator.version.prerelease
            and (
                comparator.version.major,
                comparator.version.minor,
                comparator.version.patch,
            )
            == (version.major, version.minor, version.patch)
            for comparator in comparators
        )
        if not same_patch:
            return False

    return all(_comparator_holds(version, comparator) for comparator in comparators)


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed = _as_version(version)
    return any(
        _satisfies_set(parsed, comparators) for comparators in _parse_range(range_)
    )

